// RUN: %empty-directory(%t)
// RUN: %target-swift-frontend-emit-module -emit-module-path %t/FakeDistributedActorSystems.swiftmodule -module-name FakeDistributedActorSystems -target %target-swift-5.7-abi-triple %S/Inputs/FakeDistributedActorSystems.swift
// RUN: %target-swift-frontend -typecheck -verify -target %target-swift-6.0-abi-triple -plugin-path %swift-plugin-dir -I %t %s
// REQUIRES: swift_swift_parser
// REQUIRES: concurrency
// REQUIRES: distributed

// The '$P' stub generated by '@Resolvable' can only be resolved as a remote
// reference, never created as a local instance

import Distributed
import FakeDistributedActorSystems

@Resolvable // expected-note{{in expansion of macro 'Resolvable' on protocol 'Greeter' here}}
protocol Greeter: DistributedActor where ActorSystem == FakeActorSystem {
  distributed func greet() -> String
}
// expected-expansion@-1:2{{expected-note@6:3{{'init(actorSystem:)' has been explicitly marked unavailable here}}}}

func resolveStub(system: FakeActorSystem) throws {
  // OK: resolving produces a remote reference
  _ = try $Greeter.resolve(id: .init(parse: "x"), using: system)
}

func createStubLocally(system: FakeActorSystem) {
  _ = $Greeter(actorSystem: system) // expected-error{{'init(actorSystem:)' is unavailable: stub '$Greeter' can only be resolved as a remote reference, use '$Greeter.resolve(id:using:)'}}
}
